mapper.codeEditorJavascript:
const transactions = input.edges || [];
const targetDate = input.date; // = 1.Date, EST "yesterday"

let totals = { TotalSales: 0, ChargeFee: 0, DisputeReversalNet: 0 };

if (Array.isArray(transactions)) {
    transactions.forEach(edge => {
        const node = edge.node;
        if (!node || !node.transactionDate) return;

        const transactionDateET = new Date(node.transactionDate)
            .toLocaleDateString('en-CA', { timeZone: 'America/New_York' });

        if (transactionDateET === targetDate) {
            const type = (node.type || "").toUpperCase();

            if (type === "CHARGE") {
                const gross = parseFloat(node.amount?.amount || 0);
                const fee = parseFloat(node.fee?.amount || 0);

                totals.TotalSales += gross;
                totals.ChargeFee += fee;
            }

            if (type === "DISPUTE_REVERSAL") {
                const net = parseFloat(node.net?.amount || 0);
                totals.DisputeReversalNet += net;
            }
        }
    });
}

totals.TotalSales = Math.round(totals.TotalSales * 100) / 100;
totals.ChargeFee = Math.round(totals.ChargeFee * 100) / 100;
totals.DisputeReversalNet = Math.round(totals.DisputeReversalNet * 100) / 100;

return totals;

const chargebackTable = input.chargebacks?.tableData;
const refundTable     = input.Refund?.tableData;
const targetDate      = input.date;

let result = {
    ChargebackAmount : 0,
    ChargebackCount  : 0,
    ChargebackFee    : 0,
    ChargebackTotal  : 0,
    RefundAmount     : 0
};

const chargebackRows = chargebackTable?.rows || [];
chargebackRows.forEach(row => {
    if ((row.day || "").slice(0, 10) === targetDate) {
        result.ChargebackAmount = parseFloat(row.chargeback_amount || 0);
        result.ChargebackCount  = parseInt(row.chargebacks || 0, 10);
    }
});

result.ChargebackFee   = result.ChargebackCount * 15;
result.ChargebackTotal = Math.round((result.ChargebackAmount + result.ChargebackFee) * 100) / 100;

const refundRows = refundTable?.rows || [];
refundRows.forEach(row => {
    if ((row.day || "").slice(0, 10) === targetDate) {
        result.RefundAmount = Math.round(parseFloat(row.refunded_payments || 0) * 100) / 100;
    }
});

return result;

const dateStr = input.date;

const day = parseInt(dateStr.split('-')[2], 10);

const row = day + 1;

const formula = `=I${row}+H${row}-(B${row}+C${row}+D${row}+E${row}+F${row}+G${row})`;

// Weekly Profit formula now references column J
let profitFormula = "";
if ([7, 14, 21, 28].includes(day)) {
    const endRow = row;
    const startRow = endRow - 6;
    profitFormula = `=SUM(J${startRow}:J${endRow})`;
}

return {
    row: row,
    formula: formula,
    profitFormula: profitFormula
};
